declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/health_network_v590.php';if(!hn590_bool('health_network_v590_public_pharmacies',true)){http_response_code(404);exit('Pharmacy directory unavailable.');}if(!hn590_enabled()){http_response_code(404);exit;}$all=hn590_pharmacies(true);$q=trim((string)($_GET['q']??''));if($q!=='')$all=array_values(array_filter($all,fn($p)=>stripos(($p['name'].' '.$p['area'].' '.$p['address']),$q)!==false));hn590_track('pharmacy_directory');hn590_public_header('Pharmacies','Browse verified local pharmacies and prescription-aware ordering workflows.');
?><main><section class="hn590-pagehero pharmacy"><div class="hn590-shell"><span>PHARMACY NETWORK</span><h1>Find a verified pharmacy near you.</h1><p>Browse local providers, pickup/delivery options and published stock. Prescription-required items require a valid prescription and pharmacy review.</p><form><input name="q" value="<?=e($q)?>" placeholder="Search pharmacy or area"><button class="hn590-btn primary">Search</button></form></div></section><section class="hn590-section"><div class="hn590-shell"><div class="hn590-list-grid"><?php if(!$all):?><div class="hn590-empty">No matching verified pharmacies found.</div><?php endif;?><?php foreach($all as $p):?><article class="hn590-provider"><div class="hn590-provider-logo">▣</div><div><div><span class="hn590-badge">VERIFIED</span><?php if($p['featured']):?><span class="hn590-badge gold">FEATURED</span><?php endif;?></div><h2><?=e($p['name'])?></h2><p>⌖ <?=e($p['address']?:$p['area'])?></p><div class="hn590-pills"><span><?=$p['delivery_available']?'Delivery available':'No delivery'?></span><span><?=$p['pickup_available']?'Pickup available':'No pickup'?></span><span><?=e($p['phone']?:'Contact via portal')?></span></div><a class="hn590-btn primary" href="/pharmacy.php?id=<?=(int)$p['id']?>">Browse Pharmacy</a><?php if($p['map_url']):?><a class="hn590-btn" target="_blank" rel="noopener" href="<?=e($p['map_url'])?>">Map ↗</a><?php endif;?></div></article><?php endforeach;?></div></div></section></main><?php hn590_public_footer();?>
